import React from "react";
import { useState, useEffect } from "react";
import axios from "axios";
import { Link } from "react-router-dom";

const Summary = () => {
  const [ holdingsCount , setHoldingsCount ] = useState(0);
  const [ marginAvailable, setMarginAvailable] = useState(3740);
  const [user , setUser] = useState(null);


  useEffect(()=>{
    axios.get("http://localhost:3002/api/user").then((res)=>{
      setUser(res.data);
    }).catch((err)=>{
      console.log("Error fetching user")
    })
  })


  useEffect(()=>{
    axios.get("http://localhost:3002/allHoldings").then((res)=>{
       setHoldingsCount(res.data.length);
    }).catch((err)=>{
      console.log("Error fetching holding:", err);
    })
  }, [])
  return (
    <>
      <div className="username">
        <h6>{user?.fullName || "User"}</h6>
        <hr className="divider" />
      </div>

      <div className="section">
        <span>
          <p>Equity</p>
        </span>

        <div className="data">
          <div className="first">
            <h3>{marginAvailable.toLocaleString}</h3>
            <p>Margin Available</p>
          </div>
          <hr />

          <div className="second">
            <p>
              Margins used <span>0</span>{" "}
            </p>
            <p>
              Opening balance <span>{marginAvailable.toLocaleString}</span>{" "}
            </p>
          </div>
        </div>
        <hr className="divider" />
      </div>

      <div className="section">
        <span>
          <p>Holdings({holdingsCount})</p>
        </span>

        <div className="data">
          <div className="first">
            <h3 className="profit">
              1.55k <small>+5.20%</small>{" "}
            </h3>
            <p>P&L</p>
          </div>
          <hr />

          <div className="second">
            <p>
              Current Value <span>31.43k</span>{" "}
            </p>
            <p>
              Investment <span>29.88k</span>{" "}
            </p>
          </div>
        </div>
        <hr className="divider" />
      </div>
    </>
  );
};

export default Summary;
